"use client";

import { useState, useTransition } from "react";
import { ArrowLeft, ArrowRight, Check, CircleHelp, Sparkles } from "lucide-react";
import { GOAL_TRANSITION_PREVIEW_SECTIONS } from "../presentation/goalTransitionPreviewNavigation";
import { GOAL_TRANSITION_PROTOCOL_REVIEW_ROUTE } from "../presentation/goalTransitionProtocolReviewHandoff";

const SECTIONS = [
  ["completion", "Completion Review"], ["objective", "Primary Goal"], ["guardrails", "Guardrails"], ["evidence", "How Progress Will Be Measured"],
  ["operating", "Calibration"], ["strategy", "Protocol Transition"], ["commitments", "Routine Preview"], ["cadence", "Briefing Cadence"], ["supporting", "Supporting Objectives"], ["review", "Final Review"],
];
const OBJECTIVES = ["Build Lean Mass", "Maintain Current Physique", "Improve Strength", "Improve Athletic Performance", "Custom Objective"];

export default function GoalTransitionPreviewScreen({
  draft: initialDraft,
  initialSection = "completion",
  markReadyAction,
  saveAction,
  routeBase = "/preview/goals/transition",
  protocolReviewRoute = GOAL_TRANSITION_PROTOCOL_REVIEW_ROUTE,
}) {
  const [draft, setDraft] = useState(initialDraft);
  const initialIndex = Math.max(0, GOAL_TRANSITION_PREVIEW_SECTIONS.indexOf(initialSection));
  const [index, setIndex] = useState(initialIndex);
  const [pending, startTransition] = useTransition();
  const [message, setMessage] = useState("");
  const [measurementEditing, setMeasurementEditing] = useState(false);
  const section = SECTIONS[index][0];
  const percent = ((index + 1) / SECTIONS.length) * 100;

  const persist = (sectionId, patch, nextIndex = index) => startTransition(async () => {
    setMessage("");
    try {
      const next = await saveAction({ section: sectionId, patch, currentSection: SECTIONS[nextIndex][0] });
      setDraft(next);
      navigate(nextIndex);
    } catch (error) { setMessage(error.message); }
  });
  const navigate = (nextIndex) => {
    const bounded = Math.max(0, Math.min(nextIndex, SECTIONS.length - 1));
    setIndex(bounded);
    window.history.replaceState(null, "", `${routeBase}?section=${SECTIONS[bounded][0]}`);
  };
  const continueFlow = () => persist(section, sectionPatch(section, draft), Math.min(index + 1, SECTIONS.length - 1));

  return (
    <main className="app-surface mx-auto min-h-screen w-full max-w-[393px] overflow-x-hidden pb-[calc(7rem+env(safe-area-inset-bottom))]">
      <div className="px-4 pt-8">
        <header className="mb-5">
          <div className="flex flex-col items-start gap-2">
            <div><p className="text-xs font-extrabold uppercase tracking-[0.14em] text-[var(--primary)]">Goal creation</p><h1 className="mt-1 text-2xl font-extrabold text-[var(--text-primary)]">Visible Abs <span className="text-[var(--text-muted)]">→</span> What’s Next</h1></div>
            <span className="rounded-full bg-emerald-50 px-3 py-1.5 text-[11px] font-extrabold text-emerald-700">Completion Recommended</span>
          </div>
          <div className="mt-4 h-1.5 overflow-hidden rounded-full bg-[var(--surface-soft)]"><div className="h-full rounded-full bg-[var(--primary)] transition-all" style={{ width: `${percent}%` }} /></div>
          <div className="mt-2 flex justify-between text-[11px] font-bold text-[var(--text-muted)]"><span>{SECTIONS[index][1]}</span><span>{index + 1} / {SECTIONS.length}</span></div>
        </header>

        <section className="rounded-[24px] border border-[var(--divider)] bg-[var(--surface-elevated)] p-4 shadow-sm" data-testid={`transition-section-${section}`}>
          <SectionContent draft={draft} measurementEditing={measurementEditing} section={section} setDraft={setDraft} setMeasurementEditing={setMeasurementEditing} />
        </section>
        {message && <p className="mt-3 rounded-xl bg-red-50 p-3 text-sm font-bold text-red-700">{message}</p>}
        <nav className="mt-5 flex gap-3" data-testid="transition-page-actions">
            <button className="flex min-h-12 flex-1 items-center justify-center gap-2 whitespace-nowrap rounded-[14px] border border-[var(--divider)] bg-[var(--surface-elevated)] text-sm font-extrabold disabled:opacity-40" disabled={index === 0 || pending} onClick={() => navigate(index - 1)}><ArrowLeft size={17}/> Back</button>
            {section === "review" ? <button className="flex min-h-12 flex-[1.5] items-center justify-center gap-2 rounded-[14px] bg-[var(--primary)] text-sm font-extrabold text-white disabled:opacity-50" disabled={pending} onClick={() => startTransition(async()=>{try{setDraft(await markReadyAction());window.location.assign(protocolReviewRoute);}catch(error){setMessage(error.message);}})}><Check size={17}/> Create Goal</button>
              : <button className="flex min-h-12 flex-[1.5] items-center justify-center gap-2 whitespace-nowrap rounded-[14px] bg-[var(--primary)] text-sm font-extrabold text-white disabled:opacity-50" disabled={pending} onClick={continueFlow}>Next <ArrowRight size={17}/></button>}
        </nav>
      </div>
    </main>
  );
}

function SectionContent({ draft, measurementEditing, section, setDraft, setMeasurementEditing }) {
  if (section === "completion") return <Section title="You’re ready to choose what comes next." intro="You’ve reached the end of this goal. We’ll use what you accomplished—and where you are today—to establish your next destination. Nothing changes until you make the final choice."><Callout><Fact text="Your latest DEXA shows 7.7% body fat."/><Fact text="Your latest progress photos show you’ve reached your goal."/><Fact text="All of the evidence points to this goal being complete."/><Fact text="The final decision is yours."/></Callout></Section>;
  if (section === "objective") return <Section mode="decision" title="What comes next?" intro="Based on what you accomplished, here’s the strongest next direction. You can choose a different focus if it fits you better."><ChoiceGrid values={OBJECTIVES} selected={draft.primaryObjective.title} onSelect={(title)=>setDraft({...draft,primaryObjective:{...draft.primaryObjective,title,type:slug(title)}})}/>{draft.primaryObjective.title==="Custom Objective"&&<input className="input-shell mt-3 w-full" onChange={(e)=>setDraft({...draft,primaryObjective:{...draft.primaryObjective,title:e.target.value}})} placeholder="What would you like to work toward?"/>}<Why text="You’re starting from a lean, well-measured position. That creates a strong opportunity to focus on building muscle without giving back the result you just earned."/></Section>;
  if (section === "guardrails") return <Section mode="decision" title="What should we protect?" intro="These help keep your goal on track. If one begins drifting, PhysiqueOS will let you know before it becomes a bigger problem."><div className="space-y-2">{draft.guardrails.filter((item)=>item.recommendationSource!=="user").map((item)=><button aria-pressed={item.accepted} className={`flex w-full items-start gap-3 rounded-2xl border p-4 text-left transition-colors ${item.accepted?"border-[var(--primary)] bg-[color-mix(in_srgb,var(--primary)_12%,var(--surface-elevated))]":"border-[var(--divider)] bg-[var(--surface-elevated)]"}`} key={item.id} onClick={()=>setDraft({...draft,guardrails:draft.guardrails.map((g)=>g.id===item.id?{...g,accepted:!g.accepted}:g)})}><span className={`mt-0.5 grid size-5 shrink-0 place-items-center rounded-md ${item.accepted?"bg-[var(--primary)] text-white":"bg-[var(--surface-soft)]"}`}>{item.accepted&&<Check size={13}/>}</span><span className="block text-sm font-extrabold text-[var(--text-primary)]">{item.text}</span></button>)}</div>{draft.guardrails.filter((item)=>item.recommendationSource==="user").map((item)=><input aria-label="Custom guardrail" className="input-shell mt-3 w-full" key={item.id} onChange={(e)=>setDraft({...draft,guardrails:draft.guardrails.map((g)=>g.id===item.id?{...g,text:e.target.value}:g)})} value={item.text}/>)}<button className="mt-3 text-sm font-extrabold text-[var(--primary)]" onClick={()=>setDraft({...draft,guardrails:[...draft.guardrails,{id:`${draft.id}_guardrail_custom_${draft.guardrails.length}`,text:"",accepted:true,recommendationSource:"user"}]})}>+ Add your own</button></Section>;
  if (section === "evidence") {const toggle=(group,id)=>setDraft({...draft,evidenceStrategy:{...draft.evidenceStrategy,[group]:draft.evidenceStrategy[group].map((item)=>item.id===id?{...item,accepted:!item.accepted}:item)}});return <Section title="How we’ll measure progress" intro="We’ll use a few strong measures to judge the result, then watch the signs between check-ins to make sure you’re moving in the right direction."><EvidenceGroup editing={measurementEditing} title="We’ll primarily judge progress by" items={draft.evidenceStrategy.outcomeMeasures} onToggle={(id)=>toggle("outcomeMeasures",id)}/><EvidenceGroup editing={measurementEditing} title="Between DEXA scans we’ll watch" items={draft.evidenceStrategy.predictiveSignals} onToggle={(id)=>toggle("predictiveSignals",id)}/><EvidenceGroup editing={measurementEditing} title="We’ll also monitor" items={draft.evidenceStrategy.explanatorySignals} onToggle={(id)=>toggle("explanatorySignals",id)}/><button className="mt-1 min-h-11 rounded-xl border border-[var(--divider)] px-4 text-sm font-extrabold text-[var(--primary)]" onClick={()=>setMeasurementEditing(!measurementEditing)} type="button">{measurementEditing?"Done Customizing":"Customize Measurement Strategy"}</button></Section>;}
  if (section === "operating") return <Section title="Let’s begin with calibration." intro="We know where you’re starting, but we still need to learn the intake and activity level that lets you maintain this condition while supporting productive training."><Callout><p className="font-extrabold text-[var(--text-primary)]">The first phase is about learning.</p><p className="mt-1 text-sm font-semibold leading-6 text-[var(--text-secondary)]">We’ll watch weekly weight trends, training, food, activity, and recovery—then make small adjustments instead of reacting to daily noise.</p></Callout><TwoLists left={["What we know",...draft.operatingState.known]} right={["What we’ll learn",...draft.operatingState.unknown]}/></Section>;
  if (section === "strategy") return <Section mode="decision" title="What should happen to your protocols next?" intro="Your current protocols stay with your completed goal. Here, you’re only deciding what should carry forward. After creating the goal, we’ll review and create the protocol versions that will support it."><div className="space-y-3">{draft.protocolReviews.map((item)=><article className="rounded-2xl border border-[var(--divider)] p-3" key={item.id}><div><p className="font-extrabold text-[var(--text-primary)]">{item.name}</p><p className="mt-1 text-xs font-semibold text-[var(--text-muted)]">{plainCurrentProtocol(item)}</p></div><p className="mt-2 text-xs font-semibold leading-5 text-[var(--text-secondary)]">{plainProtocolReason(item)}</p><label className="mt-3 block text-[10px] font-extrabold uppercase tracking-[.1em] text-[var(--text-muted)]">For your next goal</label><select aria-label={`${item.name} choice`} className="input-shell mt-1 w-full" onChange={(e)=>setDraft({...draft,protocolReviews:draft.protocolReviews.map((row)=>row.id===item.id?{...row,selectedDisposition:e.target.value,editStatus:e.target.value==="modify"?"review_required":"unchanged"}:row)})} value={item.selectedDisposition}>{[["keep","Carry forward"],["modify","Review and update"],["replace","Replace"],["pause","Pause"],["remove","Leave behind"]].map(([value,label])=><option key={value} value={value}>{label}</option>)}</select>{item.selectedDisposition==="modify"&&<p className="mt-2 rounded-xl bg-[var(--surface-muted)] p-3 text-xs font-semibold leading-5 text-[var(--text-secondary)]">We’ll review this protocol after you create the goal. Nothing is being edited here.</p>}</article>)}</div><Callout>Your current protocols remain part of your completed goal. The next step creates new versions only where this new goal needs them.</Callout></Section>;
  if (section === "commitments") return <Section title="Your Routine" intro="Here’s what your routine will look like based on the direction you’ve chosen. We’ll review the supporting protocols after you create the goal."><GroupedCommitments items={draft.generatedCommitments}/><Callout><strong>Changed:</strong> You’ll receive two coaching updates each week instead of daily.</Callout></Section>;
  if (section === "cadence") return <Section mode="decision" title="How often should we review progress?" intro="Your daily evidence will still be collected. This only changes how often PhysiqueOS brings everything together into a coaching update."><ChoiceGrid values={["Daily","Twice Weekly","Weekly","Custom"]} selected={titleCase(draft.briefingCadence.type)} onSelect={(label)=>setDraft({...draft,briefingCadence:{...draft.briefingCadence,type:slug(label)}})}/>{draft.briefingCadence.type==="twice_weekly"&&<ChoiceGrid multiple values={["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"]} selected={draft.briefingCadence.days.map(titleCase)} onSelect={(day)=>{const key=day.toLowerCase();setDraft({...draft,briefingCadence:{...draft.briefingCadence,days:draft.briefingCadence.days.includes(key)?draft.briefingCadence.days.filter((x)=>x!==key):[...draft.briefingCadence.days,key]}})}}/>}<Why text="Muscle gain and maintenance are easier to understand across several days. Twice-weekly updates give you useful feedback without overreacting to normal daily changes."/></Section>;
  if (section === "supporting") return <Section mode="decision" title="Anything you’d like to emphasize?" intro="Now that we’ve established your main goal, are there any muscle groups you’d especially like to prioritize during this phase?"><ChoiceGrid multiple values={draft.supportingObjectives.map((x)=>displayMuscleGroup(x.title))} selected={draft.supportingObjectives.filter((x)=>x.accepted).map((x)=>displayMuscleGroup(x.title))} onSelect={(title)=>setDraft({...draft,supportingObjectives:draft.supportingObjectives.map((x)=>displayMuscleGroup(x.title)===title?{...x,accepted:!x.accepted}:x)})}/><button className="text-sm font-extrabold text-[var(--primary)]" type="button">Something else?</button><p className="mt-2 text-xs font-semibold leading-5 text-[var(--text-muted)]">More ways to personalize this emphasis will come later. These choices refine your focus without changing your main goal.</p></Section>;
  return <Review draft={draft}/>;
}

function sectionPatch(section,draft){return ({objective:draft.primaryObjective,guardrails:draft.guardrails,supporting:draft.supportingObjectives,evidence:draft.evidenceStrategy,operating:draft.operatingState,strategy:draft.protocolReviews,commitments:draft.generatedCommitments,cadence:draft.briefingCadence})[section]??{};}
function Review({draft}) { const accepted=draft.guardrails.filter(x=>x.accepted); return <Section title="Your New Goal" intro="You’re creating your next goal. Immediately afterward, we’ll review the protocols that support it."><ReviewBlock title="Primary Goal" value={draft.primaryObjective.title}/><ReviewBlock title="Guardrails" value={accepted.length?accepted.map(x=>x.text).join(" · "):"Nothing selected yet"}/><ReviewBlock title="Areas to Prioritize" value={draft.supportingObjectives.filter(x=>x.accepted).map(x=>displayMuscleGroup(x.title)).join(", ")||"No additional emphasis"}/><ReviewBlock title="Starting Point" value="Build from your current lean condition"/><ReviewBlock title="Calibration" value="Learn the intake and activity level that supports productive training"/><ReviewBlock title="Briefing Rhythm" value={`${titleCase(draft.briefingCadence.type)}${draft.briefingCadence.days?.length?` · ${draft.briefingCadence.days.map(titleCase).join(" and ")}`:""}`}/><ReviewBlock title="Where You’re Starting" value={`${draft.openingBaseline.date||"Date unavailable"} · ${fmt(draft.openingBaseline.dexaWeight," lb")} · ${fmt(draft.openingBaseline.leanMass," lb lean mass")} · ${fmt(draft.openingBaseline.bodyFatPercentage,"% body fat")}`}/><ReviewBlock title="What We’ll Learn" value={draft.operatingState.unknown.join(" · ")}/><div className="mt-5 border-t border-[var(--divider)] pt-5"><h3 className="text-base font-extrabold text-[var(--text-primary)]">Next Step</h3><p className="mt-2 text-sm font-semibold leading-6 text-[var(--text-secondary)]">This creates your next goal. After that, we’ll review the protocols that will support it, carrying forward what still works and updating what needs to change for this new phase.</p></div></Section>;}
function Section({children,intro,mode="review",title}){return <><div className="flex items-center gap-2 text-[var(--primary)]"><Sparkles size={18}/><p className="text-xs font-extrabold uppercase tracking-[.12em]">{mode==="decision"?"Your decision":"Coach recommendation"}</p></div><h2 className="mt-3 text-[26px] font-extrabold leading-tight text-[var(--text-primary)]">{title}</h2><p className="mb-5 mt-2 text-sm font-semibold leading-6 text-[var(--text-secondary)]">{intro}</p>{children}</>;}
function Callout({children}){return <div className="mt-3 rounded-2xl bg-[var(--surface-muted)] p-4 text-sm font-semibold leading-6 text-[var(--text-secondary)]">{children}</div>;}
function Fact({text}){return <p className="flex gap-2"><Check className="mt-1 shrink-0 text-emerald-600" size={15}/><span>{text}</span></p>;}
function ChoiceGrid({multiple=false,onSelect,selected,values}){return <div className="my-3 flex flex-wrap gap-2">{values.map(value=>{const active=multiple?selected.includes(value):selected===value;return <button aria-pressed={active} className={`min-h-11 rounded-xl border px-3 py-2 text-left text-sm font-extrabold ${active?"border-[var(--primary)] bg-[color-mix(in_srgb,var(--primary)_12%,var(--surface-elevated))] text-[var(--text-primary)]":"border-[var(--divider)] text-[var(--text-secondary)]"}`} key={value} onClick={()=>onSelect(value)} type="button">{active&&<Check className="mr-1 inline text-[var(--primary)]" size={14}/>} {value}</button>})}</div>;}
function ToggleRow({active,label,onClick}){return <button className={`flex min-h-12 w-full items-center gap-3 rounded-xl border p-3 text-left text-sm font-bold ${active?"border-indigo-300 bg-indigo-50":"border-[var(--divider)]"}`} onClick={onClick}><span className={`grid size-5 place-items-center rounded-md ${active?"bg-indigo-600 text-white":"bg-[var(--surface-soft)]"}`}>{active&&<Check size={13}/>}</span>{label}</button>;}
function Why({text}){return <details className="mt-4 rounded-xl border border-[var(--divider)] p-3"><summary className="flex cursor-pointer list-none items-center gap-2 text-xs font-extrabold text-[var(--primary)]"><CircleHelp size={15}/> Why this?</summary><p className="mt-2 text-xs font-semibold leading-5 text-[var(--text-secondary)]">{text}</p></details>;}
function EvidenceGroup({editing,items,onToggle,title}){return <div className="mb-5"><h3 className="mb-2 text-sm font-extrabold text-[var(--text-primary)]">{title}</h3><div className="space-y-2">{items.map(item=>editing?<button aria-pressed={item.accepted} className={`w-full rounded-xl border p-3 text-left ${item.accepted?"border-[var(--primary)] bg-[color-mix(in_srgb,var(--primary)_8%,var(--surface-elevated))]":"border-dashed border-[var(--divider)] opacity-60"}`} key={item.id} onClick={()=>onToggle(item.id)}><p className="text-sm font-extrabold text-[var(--text-primary)]">{item.accepted&&<Check className="mr-1 inline text-emerald-600" size={14}/>} {plainEvidenceLabel(item)}</p><p className="mt-1 text-xs font-semibold leading-5 text-[var(--text-muted)]">{plainEvidenceExplanation(item)}</p></button>:<article className="rounded-xl border border-[var(--divider)] bg-[var(--surface-elevated)] p-3" key={item.id}><p className="text-sm font-extrabold text-[var(--text-primary)]">{plainEvidenceLabel(item)}</p><p className="mt-1 text-xs font-semibold leading-5 text-[var(--text-muted)]">{plainEvidenceExplanation(item)}</p></article>)}</div></div>;}
function TwoLists({left,right}){return <div className="mt-4 grid grid-cols-2 gap-3">{[left,right].map((list,i)=><div className="rounded-xl border border-[var(--divider)] p-3" key={list[0]}><p className="mb-2 text-xs font-extrabold text-[var(--text-primary)]">{list[0]}</p>{list.slice(1).map(x=><p className="mb-1 text-[11px] font-semibold leading-4 text-[var(--text-muted)]" key={x}>{i?"Pending: ":"✓ "}{x}</p>)}</div>)}</div>;}
function GroupedCommitments({items}){return <div className="space-y-4">{["daily","weekly","periodic"].map(f=><div key={f}><h3 className="mb-2 text-xs font-extrabold uppercase tracking-[.1em] text-[var(--text-muted)]">{({daily:"Every Day",weekly:"Every Week",periodic:"Periodically"})[f]}</h3>{items.filter(x=>x.frequency===f&&x.accepted).map(x=><div className="mb-2 flex w-full gap-2 rounded-xl bg-[var(--surface-muted)] p-3 text-left" key={x.id}><Check className="mt-0.5 shrink-0 text-emerald-600" size={15}/><div><p className="text-xs font-extrabold text-[var(--text-primary)]">{plainRoutineText(x.requirement)}</p>{routineChange(x.requirement)&&<p className="mt-1 text-[10px] font-extrabold uppercase tracking-[.08em] text-[var(--primary)]">{routineChange(x.requirement)}</p>}</div></div>)}</div>)}</div>;}
function ReviewBlock({title,value}){return <div className="mb-3 rounded-xl bg-[var(--surface-muted)] p-3"><p className="text-[10px] font-extrabold uppercase tracking-[.1em] text-[var(--text-muted)]">{title}</p><p className="mt-1 text-sm font-bold leading-5 text-[var(--text-primary)]">{value}</p></div>;}
function fmt(value,suffix){return value==null?"Unavailable":`${value}${suffix}`;}
function slug(value){return value.toLowerCase().replaceAll(" ","_");}
function titleCase(value){return String(value).replaceAll("_"," ").replace(/\b\w/g,c=>c.toUpperCase());}
function displayMuscleGroup(value){return value==="Lower Body"?"Legs":value;}
function plainEvidenceLabel(item){return ({dexa_lean_mass:"DEXA Lean Mass",dexa_fat_mass:"DEXA Fat Mass",dexa_body_fat:"DEXA Body Fat %",progressive_overload:"Training Progression",training_trend:"Training Performance",scale_weight:"Scale Weight",progress_photos:"Progress Photos",calories:"Nutrition",protein:"Protein",macros:"Carbohydrates and Fats",activity:"Activity",recovery:"Recovery",sleep:"Sleep",adherence:"Plan Consistency"})[item.evidenceType]??item.label;}
function plainEvidenceExplanation(item){return ({dexa_lean_mass:"This shows whether you’re actually adding lean tissue.",dexa_fat_mass:"This helps confirm that added weight is not coming mainly from body fat.",dexa_body_fat:"This tells us whether you’re building muscle while staying lean.",progressive_overload:"Steady improvements in reps, load, or quality help show that training is creating a reason to grow.",training_trend:"Patterns across several workouts tell us more than one unusually strong or weak session.",scale_weight:"We’ll watch your weight trend, but weight alone can’t tell us whether you’re gaining muscle or fat. We’ll interpret it alongside training, photos, and future DEXA scans.",progress_photos:"Photos help us see changes in shape, fullness, and proportion between DEXA scans.",calories:"Enough energy supports training and growth; too much too quickly can push body fat beyond your guardrail.",protein:"Consistent protein gives your body the material it needs to repair and build muscle.",macros:"Carbohydrates support training performance, while dietary fat helps keep the plan sustainable and balanced.",activity:"Activity changes how much food you need and helps explain shifts in weight and recovery.",recovery:"Recovery tells us whether your training load and energy intake are sustainable.",sleep:"Sleep affects training quality, appetite, recovery, and your ability to keep progressing.",adherence:"Consistent execution helps us tell whether the plan needs to change or simply needs more time."})[item.evidenceType]??item.explanation;}
function plainProtocolReason(item){return ({energy:"Your next goal needs maintenance calibration instead of a sustained deficit.",nutrition:"Protein still matters, while calories and macros may need to rise to support training.",training:"Your current training structure can carry forward while we refine muscle-building emphasis.",activity:"Activity can continue, but the previous target should no longer be a fixed requirement.",recovery:"Recovery support remains useful unless your new training demands suggest a change.",weight:"Daily weights remain useful when we focus on the weekly trend.",photos:"Photos remain useful for checking shape and proportion between scans.",dexa:"DEXA gives the clearest measure of muscle gain while you stay lean.",briefings:"Two coaching updates each week fit slower body-composition changes better than daily summaries."})[item.category]??item.recommendationReason;}
function plainCurrentProtocol(item){return ({energy:"Current cut intake and activity approach",recovery:"Current recovery routine",weight:"Daily weight tracking",photos:"Current progress-photo schedule",dexa:"Current DEXA schedule",briefings:"Current coaching-update schedule"})[item.category]??item.currentStrategy;}
function plainRoutineText(value){return value.replace("Log morning weight.","Record your morning weight.").replace("Log nutrition.","Record your meals and nutrition.");}
function routineChange(value){if(/calorie intake and activity together|energy-balance/i.test(value))return "New: weekly energy-balance review";return null;}
